pm.test("Status code deve ser 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Resposta deve conter mensagem de sucesso", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("message");
    pm.expect(response.message).to.eql("Cadastro realizado com sucesso");
});

pm.test("Resposta deve retornar _id", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("_id");
    pm.expect(response._id).to.be.a("string");
});

const response = pm.response.json();

pm.environment.set("userId", response._id);

pm.test("Não deve permitir e-mail duplicado", function () {
    pm.expect(pm.response.code).to.be.oneOf([400, 409]);
});

pm.test("Deve retornar mensagem de erro", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("message");
});

